import re


def title_of(html: str) -> str:
    """Return the text between <title> and </title> in html, or "".

    Rules:
    - Only the first <title> element is considered.
    - Tag names are matched case-insensitively, and the opening tag may
      carry attributes (e.g. ``<title lang="en">``). A tag such as
      ``<titlex>`` is not a title tag.
    - The text is returned exactly as written, with no stripping and no
      entity decoding, and may span multiple lines.
    - If there is no title element, or the opening tag has no matching
      closing tag, return "".
    - The function works only on the given string and never uses the network.
    """
    opening = re.search(r"<title(?:\s[^>]*)?>", html, re.IGNORECASE)
    if opening is None:
        return ""
    closing = re.compile(r"</title\s*>", re.IGNORECASE).search(html, opening.end())
    if closing is None:
        return ""
    return html[opening.end():closing.start()]


def test_basic_title() -> None:
    html = "<html><head><title>Hello</title></head><body></body></html>"
    assert title_of(html) == "Hello"


def test_no_title_returns_empty() -> None:
    assert title_of("<html><head></head><body>hi</body></html>") == ""


def test_empty_string_input() -> None:
    assert title_of("") == ""


def test_empty_title_element() -> None:
    assert title_of("<title></title>") == ""


def test_case_insensitive_tags() -> None:
    assert title_of("<HTML><TITLE>Upper</TITLE></HTML>") == "Upper"
    assert title_of("<Title>Mixed</tItLe>") == "Mixed"


def test_opening_tag_with_attributes() -> None:
    assert title_of('<title lang="en">Attr</title>') == "Attr"


def test_similar_tag_name_is_not_title() -> None:
    assert title_of("<titlex>Nope</titlex>") == ""


def test_missing_closing_tag() -> None:
    assert title_of("<html><title>Unclosed<body></body></html>") == ""


def test_only_closing_tag() -> None:
    assert title_of("</title>") == ""


def test_first_title_wins() -> None:
    assert title_of("<title>One</title><title>Two</title>") == "One"


def test_multiline_title_preserved() -> None:
    assert title_of("<title>\n  Line one\n  Line two\n</title>") == "\n  Line one\n  Line two\n"


def test_whitespace_not_stripped() -> None:
    assert title_of("<title>  padded  </title>") == "  padded  "


def test_entities_not_decoded() -> None:
    assert title_of("<title>Tom &amp; Jerry</title>") == "Tom &amp; Jerry"


def test_title_in_body_text_after_content() -> None:
    html = "<p>intro</p><title>Late</title><p>outro</p>"
    assert title_of(html) == "Late"
